  EXPECT_EQ(fmt::format("{0:{width}}", -42, fmt::arg("width", 4)), " -42");
  EXPECT_EQ(fmt::format("{value:{width}}", fmt::arg("value", -42),
                        fmt::arg("width", 4)),
            " -42");
