TEST(format_test, zero_flag_and_align) {
  // If the 0 character and an align option both appear, the 0 character is
  // ignored.
  EXPECT_EQ(fmt::format("{:<05}", 42), "42   ");
  EXPECT_EQ(fmt::format("{:<05}", -42), "-42  ");
  EXPECT_EQ(fmt::format("{:^05}", 42), " 42  ");
  EXPECT_EQ(fmt::format("{:^05}", -42), " -42 ");
  EXPECT_EQ(fmt::format("{:>05}", 42), "   42");
  EXPECT_EQ(fmt::format("{:>05}", -42), "  -42");
}

